def simulate_natural_selection(population, generations, mutation_rate):
    import random

    def fitness(individual):
        return individual

    for _ in range(generations):
        # Calculate fitness for each individual
        fitness_scores = [fitness(individual) for individual in population]

        # Calculate total fitness
        total_fitness = sum(fitness_scores)

        # Select individuals to survive based on fitness
        survivors = []
        for _ in range(len(population)):
            r = random.random() * total_fitness
            cumulative_fitness = 0
            for individual, score in zip(population, fitness_scores):
                cumulative_fitness += score
                if r < cumulative_fitness:
                    survivors.append(individual)
                    break

        # Apply mutations
        for i in range(len(survivors)):
            if random.random() < mutation_rate:
                if random.choice([True, False]):
                    survivors[i] += 1
                else:
                    survivors[i] -= 1

        population = survivors

    return population

