def can_add_event(current_events, new_event):
    from datetime import datetime, timedelta

    def event_end_time(event):
        start_time = datetime.strptime(event["date"], "%Y-%m-%d") + datetime.strptime(event["start_time"], "%H:%M")
        return start_time + timedelta(hours=2)

    new_event_end_time = event_end_time(new_event)

    for event in current_events:
        event_end_time_obj = event_end_time(event)
        event_start_time_obj = datetime.strptime(event["date"], "%Y-%m-%d") + datetime.strptime(event["start_time"], "%H:%M")

        if (new_event_end_time >= event_start_time_obj) and (new_event_start_time <= event_end_time_obj):
            return False

    return True

def calculate_average_monthly_savings(income, expenses):
    if len(income) != len(expenses) or len(income) != 12:
        return None

    total_savings = 0
    for i in range(12):
        if not isinstance(income[i], (int, float)) or not isinstance(expenses[i], (int, float)):
            return None
        monthly_savings = income[i] - expenses[i]
        if monthly_savings < 0:
            return None  # Negative savings not allowed
        total_savings += monthly_savings

    return total_savings / 12.0

